function pushHistory(){try{history.pushState({},'');}catch{}}
export interface Settings {music:number;effects:number;muted:boolean;reduced:boolean;large:boolean;legible:boolean;skipAnimation:boolean}
export class App {
 state:State|null=null;view='title';tab='Realm';family='all';selectedNode='edo';selectedUnit='east_ii';cursor:Point={x:0,y:0};battleMode='inspect';offlineReady=false;slots:Partial<Record<Slot,Envelope>>={};settings:Settings={music:30,effects:50,muted:false,reduced:false,large:false,legible:false,skipAnimation:false};lastEvents:State['eventLog']=[];aiTimer:ReturnType<typeof setTimeout>|null=null;saveChain:Promise<void>=Promise.resolve();audio:((cue:string)=>void)|null=null;lastVisualIndex=0;saving=false;legacyExportCandidates:Envelope[]=[];
 labOptions:BattleLabOptions={...defaultLab};scene:ScenePlayer|null=null;enemyGo=false;enemyPaused=false;ringOpen=false;inspecting=false;pendingBattle:{id:string;action:BattleAction}|null=null;devOptions:DevOptions=loadDev();teacherLock=new TeacherLock();seenScenes=new Set<string>(loadSeen());mapView:'all'|'mino'='all';labReturn:{state:State|null;tab:string}|null=null;
 sound=new LocalAudio();
 get practicing(){return !!this.state?.flags.battle_lab;}
 get devRun(){return !!this.state?.flags.dev_playtest;}
 enterLab(){if(!this.labReturn)this.labReturn={state:this.state?structuredClone(this.state):null,tab:this.tab};this.view='lab-setup';this.render();}
 startLab(){if(!this.labReturn)this.labReturn={state:this.state?structuredClone(this.state):null,tab:this.tab};this.state=createBattleLab(this.labOptions);this.view='play';this.tab='Realm';this.battleMode=this.labOptions.preset==='volley'?'volley':this.labOptions.preset==='clash'?'attack':'inspect';this.selectedUnit=activeUnit(this.state)?.id??'east_ii';this.cursor=this.state.battle!.formations.find(f=>f.id===this.selectedUnit)??{x:0,y:0};this.render();}
 exitLab(){if(this.labReturn){this.state=this.labReturn.state;this.tab=this.labReturn.tab;this.labReturn=null;}this.view=this.state?'play':'title';this.battleMode='inspect';this.selectedUnit='east_ii';this.render();}
 constructor(public root:HTMLElement){this.audio=cue=>this.sound.cue(cue==='battle'?'battle-hit':cue);}
 async start(){try{Object.assign(this.settings,JSON.parse(localStorage.getItem('mc-settings')??'{}'));}catch{}await this.refreshSlots();this.root.addEventListener('click',e=>{const b=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(b&&!(b as HTMLButtonElement).disabled)this.action(b.dataset.action!);});document.addEventListener('keydown',e=>this.key(e));window.addEventListener('popstate',()=>{pushHistory();this.closeModal();});pushHistory();document.addEventListener('visibilitychange',()=>{if(document.hidden&&this.state&&safeSave(this.state))void this.save('autosave');});this.render();if(storageNotice())this.message(storageNotice());if(!(globalThis as {SEKIGAHARA_ASSETS?:unknown}).SEKIGAHARA_ASSETS&&'serviceWorker' in navigator&&/^https?:$/.test(location.protocol)){try{const registration=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;this.offlineReady=true;if(this.view==='title')this.render();registration.addEventListener('updatefound',()=>{});}catch{this.offlineReady=false;}}}
 async refreshSlots(){for(const slot of ['autosave','manual-1','manual-2','manual-3'] as Slot[])try{const e=await rawSlot(slot);if(e)this.slots[slot]=e;else delete this.slots[slot];}catch{}}
 message(message:string){this.root.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=message;e.setAttribute('role','alert');this.root.append(e);setTimeout(()=>e.remove(),5000);}
 modal(title:string,body:string,after?:()=>void){if(this.aiTimer){clearTimeout(this.aiTimer);this.aiTimer=null;}this.root.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2>${body}`;this.root.append(d);d.addEventListener('cancel',e=>{e.preventDefault();this.closeModal();});d.showModal();after?.();d.querySelector<HTMLElement>('input,select,button')?.focus();}
 closeModal(){if(this.state?.activeOrder){if(this.state.activeOrder.attempts===0&&this.state.activeOrder.context!=='crisis')this.dispatch({type:'CLOSE_ORDER'});else this.message('Resolve this calculation before leaving it.');return;}this.root.querySelector('dialog')?.close();this.root.querySelector('dialog')?.remove();this.root.querySelector<HTMLElement>('[data-action="orders"]')?.focus();if(this.state?.phase==='battle_round')this.render();}
 confirm(title:string,body:string,callback:()=>void){if(this.aiTimer){clearTimeout(this.aiTimer);this.aiTimer=null;}const previous=this.root.querySelector('dialog');if(previous)previous.close();const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(body)}</p><div class="row"><button type="button" class="primary" id="yes">Confirm</button><button type="button" id="no">Back</button></div>`;this.root.append(d);const dismiss=()=>{d.close();d.remove();if(previous)previous.showModal();};d.querySelector('#yes')!.addEventListener('click',()=>{dismiss();callback();});d.querySelector('#no')!.addEventListener('click',dismiss);d.addEventListener('cancel',e=>{e.preventDefault();dismiss();});d.showModal();d.querySelector<HTMLElement>('#yes')!.focus();}
 dispatch(c:Command){if(!this.state)return;if(this.saving&&['BATTLE','AI_TURN','WITHDRAW','BATTLE_COUNCIL'].includes(c.type)){this.message('Finishing the save snapshot; please try that command again.');return;}const old=this.state,r=reduce(old,c);if(r.events[0]?.type==='RULE_VIOLATION'){this.message(r.events[0].key);return;}if(this.devRun||r.state.flags.dev_playtest){const cleared=clearGatesWithEvents(r.state);this.state=cleared.state;this.lastEvents=[...r.events,...cleared.events];}else{this.state=r.state;this.lastEvents=r.events;}this.ringOpen=false;this.inspecting=false;this.view='play';const recorded=this.state.challengeRecords.length>old.challengeRecords.length,wrong=c.type==='ANSWER'&&!recorded&&!!this.state.activeOrder&&this.state.activeOrder.attempts>(old.activeOrder?.attempts??0);if(activeUnit(this.state)?.id!==activeUnit(old)?.id&&this.state.phase==='battle_round'){this.battleMode='inspect';this.selectedUnit=activeUnit(this.state)?.id??this.selectedUnit;}this.render();if(recorded&&!this.state.activeOrder)this.resultModal();if(this.state.pendingReward!==null)this.auditModal();if(c.type==='AUDIT_REWARD')this.modal('Your stores have been recovered',this.ledger(this.lastEvents)+btn('Continue','close-result',false,'primary'));const autosave=safeSave(this.state)&&(this.state.phase==='battle_round'||this.state.phase==='convoy_result'||this.state.phase==='convoy_briefing')||(old.phase==='chapter_report'&&this.state.phase!==old.phase)||this.state.phase==='battle_result'||this.state.phase==='chapter_report'||this.state.phase==='battle_deployment';if(autosave&&!this.practicing)void this.save('autosave');if(wrong){const d=this.root.querySelector('dialog');d?.classList.add('answer-wrong');if(!this.settings.reduced)d?.classList.add('shake-answer');d?.querySelector('.answer-feedback')?.scrollIntoView?.({block:'start'});this.audio?.('answer-incorrect');}else if(r.events.some(e=>e.type==='PRECISION_AWARDED'))this.audio?.('precision');else if(recorded)this.audio?.('confirm');else if(r.events.some(e=>e.type==='COMBAT_RESOLVED'))this.audio?.(r.events.some(e=>e.key==='volley'||e.key==='suppress')?'volley':'impact');else if(r.events.some(e=>e.type==='FORMATION_ROUTED'))this.audio?.('rout');else if(r.events.some(e=>e.type==='RESERVE_ENTERED'||e.type==='AUXILIARY_RESOLVED'))this.audio?.('reinforcement');else if(r.events.some(e=>e.type==='FORMATION_MOVED'||e.type==='WAGON_MOVED'))this.audio?.('march');else this.audio?.('click');}
 async save(slot:Slot,label?:string){if(!this.state||this.practicing||this.devRun)return;const snapshot=structuredClone(this.state);this.saving=true;if(this.aiTimer){clearTimeout(this.aiTimer);this.aiTimer=null;}this.root.classList.add('save-busy');const promise=this.saveChain.then(async()=>{const e=await envelope(snapshot,label??(slot==='autosave'?'Autosave':this.slots[slot]?.slotLabel??'Campaign '+slot.slice(-1)));await writeSlot(slot,e);this.slots[slot]=e;});this.saveChain=promise.catch(()=>{});try{await promise;if(slot!=='autosave')this.message(savedMessage());}catch{this.message('Could not save on this device. Export the campaign to keep a copy.');}finally{this.saving=false;this.root.classList.remove('save-busy');if(this.view==='play'&&this.state?.phase==='battle_round'&&!this.root.querySelector('dialog[open]')&&activeUnit(this.state)?.side==='west')this.render();}}
 plate(id:string,cls=''){const art=paintedPlates[id];return art?`<img class="plate painted ${cls}" data-asset="${id}" src="./art/scenes/${art}.webp" alt="${esc(nice(id))}">`:`<img class="plate ${cls}" data-asset="${id}" src="./art/${id}.webp" alt="${esc(nice(id))}">`;}
 frame(inner:string){return `<section class="screen">${inner}</section>`;}
 chrome(){const s=this.state!,p=pressure(s);return `<header class="top"><div class="period">CHAPTER ${s.chapterIndex} / 4<br><span class="muted">${esc(chapter(s.chapterIndex).dateStringId?text(chapter(s.chapterIndex).dateStringId):'Sekigahara')}</span></div>${(['food','currency','materials','authority'] as Resource[]).map(r=>`<button class="resource" data-action="resource:${r}" aria-label="${labelResource(r)} ${s.resources[r]}"><span>${labelResource(r)}</span><strong>${num(s.resources[r])}</strong></button>`).join('')}</header>`;}
 nav(){const s=this.state!;if(this.practicing)return `<footer class="bottom frame practice-nav"><strong>DEV · BATTLE PRACTICE</strong>${btn('Restart','lab-restart')}${btn('Change exercise','lab-config')}${btn('How to play','battle-help')}${btn('Settings','settings')}${btn('Return to campaign','lab-exit')}</footer>`;const dev=this.devRun?btn('DEV setup','dev-setup')+btn('Scenes','dev-gallery'):'';return `<footer class="bottom frame">${dev}<div class="seals" aria-label="${s.commandSeals} Command Seals remaining">${[0,1,2].map(i=>`<span class="${i<s.commandSeals?'':'seal-spent'}">◆</span>`).join(' ')}<br><small>SEALS</small></div>${btn('Map','map')}${btn('Orders','orders',s.phase!=='orders')}${btn('Chronicle','history')}${btn('Save / Load','saves')}${btn('Settings','settings')}${s.phase==='orders'?btn(s.commandSeals?'End Chapter':'End Chapter','end',s.commandSeals>0||!!s.activeOrder||s.pendingReward!==null,'primary'):''}${s.phase==='orders'&&s.commandSeals>0&&legalOrders(s).length===0&&!s.activeOrder&&s.pendingReward===null?btn('Forfeit Seals','forfeit',false,'danger'):''}</footer>`;}
render(){this.sound.update(this.state?.ending?'ending_'+this.state.ending.tier:this.view==='title'?'title':this.state?.battle?.scenarioId==='convoy'?'convoy':this.state?.phase==='battle_round'&&(this.state.battle?.round??0)>=5?'battle_late':this.state?.phase.startsWith('battle')?'battle':this.tab==='Map'?'map':'council',this.settings.music,this.settings.effects,this.settings.muted);if(this.aiTimer)clearTimeout(this.aiTimer);this.aiTimer=null;this.root.className=[this.settings.reduced?'reduced-motion':'',this.settings.large?'large-text':'',this.settings.legible?'high-legibility':''].join(' ');let html='';
 if(this.view==='title'&&__DEV_BUILD__)this.view='dev-setup';if(this.view==='dev-setup')html=this.frame(this.devSetupMarkup());
  else if(this.view==='title')html=`<section class="screen title"><div class="title-backdrop"></div><div class="title-content"><div class="eyebrow">JAPAN · 1598–1600</div><h1>MATH &<br>CIVILIZATION</h1><p class="subtitle">THE ROAD TO SEKIGAHARA</p><p class="eyebrow">TOKUGAWA IEYASU CAMPAIGN</p></div><div class="title-menu">${btn('Begin Campaign','new',false,'primary')}${btn('Continue','continue',!this.slots.autosave)}${btn(__DEV_BUILD__?'Battle Practice':'Battle Practice (teacher)','lab-config')}${btn('Load Campaign','saves')}${btn('Chronicle','history')}${btn('Settings','settings')}${btn('Credits','credits')}</div><div class="version">v${BUILD_VERSION}${storageNotice()?' · EXPORT SAVE BACKUPS':''} · ${this.offlineReady?'READY FOR OFFLINE PLAY':(globalThis as {SEKIGAHARA_ASSETS?:unknown}).SEKIGAHARA_ASSETS||location.protocol==='file:'||'__TAURI_INTERNALS__' in globalThis?'LOCAL EDITION':'OFFLINE CACHE PREPARING'}</div><div class="brand">A WILLIAM MCADA PRODUCT</div></section>`;
 else if(this.view==='setup')html=this.frame(`<div class="full-panel frame"><div class="eyebrow">CHOOSE A CAMPAIGN</div><h2>Japan — Tokugawa Ieyasu</h2><p>The Road to Sekigahara, 1598–1600</p><p>Four chapters of government and diplomacy lead to a tactical battle. Your calculations determine the supplies, equipment and support your army brings to the field.</p><label>Math guidance<select id="mode"><option value="campaign">Standard guidance — three tries</option><option value="guided">Extra hints — three tries</option><option value="scholar">Independent practice — three tries</option></select></label><p>Standard guidance gives a method hint after a mistake. Extra hints can help before submitting. Independent practice checks the answer without automatic method hints.</p><p>Every calculation gives three chances. Correct first answers earn full benefits and a bonus. Ordinary later benefits are 85% or 65%. Purchased supplies are delivered in full; their planning dividend falls from 10% to 5%, then 2%, then 0% with an adviser.</p><details class="technical-details"><summary>Replay a particular campaign (optional)</summary><label>Campaign code<input id="seed" maxlength="8" placeholder="Leave blank for a new campaign" aria-describedby="seed-help"></label><p id="seed-help" class="muted">Enter a code from a previous campaign report to repeat its starting circumstances.</p></details><div class="row">${btn('Begin','start',false,'primary')}${btn('Back','title')}</div></div>`);
 else if(this.view==='lab-setup')html=this.frame(battleLabSetup(this));
 else if(this.view==='saves')html=this.frame(this.savesMarkup());
 else if(this.view==='settings')html=this.frame(this.settingsMarkup());
 else if(this.view==='history'||this.view==='credits')html=this.frame(`<div class="full-panel frame"><div class="eyebrow">${this.view==='credits'?'CREDITS':'CHRONICLE · HISTORICAL METHOD'}</div><h2>${this.view==='credits'?'Math & Civilization':'History and your campaign'}</h2>${this.view==='credits'?'<p>A WILLIAM MCADA PRODUCT</p><p>Designed and built by William McAda · © 2026 William McAda</p><p>Original prototype illustrations and local synthesized music. v0.4 story scenes painted to the game’s art direction (AI-assisted, directed by William McAda). Campaign map coastline and province outlines: Global Map Japan, Geospatial Information Authority of Japan (GSI), via dataofjapan/land. Phaser 3 · TypeScript · Vite. Asset provenance and dependency licenses are included with the source.</p>':`<p>${esc(text('history.compression_disclosure'))}</p><p>The Toyotomi succession led to a struggle between competing coalitions. Ieyasu moved east toward the Uesugi domain, then returned west. The Eastern victory at Sekigahara in 1600 strengthened his position; he became shōgun in 1603.</p><p>Formation strengths, travel points, loyalty bands, and resource units are game-scaled. Kobayakawa’s commitment is a simulation, not a measured historical fact. Alternate endings belong to your campaign.</p><h3>Source notes</h3><p>Gifu Sekigahara Battlefield Memorial Museum · Tokugawa Art Museum · Metropolitan Museum of Art, Art of the Samurai. Full references accompany the source package.</p>`}${btn('Return','back')}</div>`);
 else if(this.state){const s=this.state;html=s.phase==='ending'?this.playMarkup():this.chrome()+this.playMarkup()+this.nav();}
 const scroll=this.root.querySelector('.battle-viewport')?.scrollLeft??0;if(__DEV_BUILD__)html=`<div class="dev-banner" role="note">DEV PLAYTEST · The Road to Sekigahara v${BUILD_VERSION} · no questions, no records</div>`+html;this.root.innerHTML=html.replace(/src="(\.\/[^"]+)"/g,(_,path)=>`src="${assetURL(path)}"`);const viewport=this.root.querySelector('.battle-viewport');if(viewport)viewport.scrollLeft=scroll;document.querySelector('#boot-status')?.remove();(globalThis as {SEKIGAHARA_READY?:boolean}).SEKIGAHARA_READY=true;this.root.querySelectorAll<HTMLImageElement>('img[data-asset]').forEach(img=>img.onerror=()=>{const e=document.createElement('div');e.className='asset-fallback';e.textContent=img.dataset.asset+' · illustration placeholder';img.replaceWith(e);});
 if(this.state&&this.view==='play'){const s=this.state;const rounds=this.root.querySelector<HTMLSelectElement>('#rounds');if(rounds)rounds.value=String(Math.max(1,Math.min(12,Math.floor((s.resources.food+s.playerArmy.protectedBattleRice)/battleQuota(s.playerArmy.formations.map(f=>f.troops))))));if(this.root.querySelector('.bv5-grid')&&this.lastVisualIndex<s.eventLog.length)animateBattle(this.root,this.lastEvents,this.settings.reduced,this.settings.skipAnimation);this.lastVisualIndex=s.eventLog.length;if(this.scene)this.root.append(this.scene.element);else this.maybeScene();if(this.root.querySelector('.geo-map'))this.wireMap();if(s.activeOrder)this.mathModal();if(s.pendingReward!==null)this.auditModal();if(!this.saving&&!this.scene&&s.phase==='battle_round'&&(!this.enemyPaused||this.enemyGo||this.practicing)&&!s.battle!.dispatchPending&&!s.battle!.councilPending&&activeUnit(s)?.side==='west'&&(!this.practicing||this.labOptions.automaticEnemy)){this.enemyGo=false;this.aiTimer=setTimeout(()=>this.dispatch({type:'AI_TURN'}),this.settings.skipAnimation?30:1100);}}
 }
 playMarkup(){const s=this.state!,c=chapter(s.chapterIndex);if(this.practicing&&s.phase==='battle_result')return practiceResult(this);if(this.tab==='Map'&&['council','orders'].includes(s.phase))return this.mapMarkup();
 switch(s.phase){
 case 'prologue':return `<div class="wide frame scroll prologue"><div class="prologue-art">${this.plate('BG_TITLE')}</div><div class="eyebrow">YOUR ROAD TO BATTLE</div><h2>Japan is moving toward war</h2><p>Hideyoshi is dead. The lords sworn to protect his heir are forming rival coalitions. As Tokugawa Ieyasu, you must bring an army to Sekigahara with the strength and support to win.</p><p><strong>You will command the battle yourself.</strong> Four chapters of council decisions lead to a compact tactical field: move your cavalry, spears and gunners, hold the enemy camp, or force its army to retreat.</p><div class="resource-purpose"><p><strong>Rice</strong> keeps your soldiers supplied.</p><p><strong>Treasury</strong> buys their equipment.</p><p><strong>Materials</strong> build defenses and buy ammunition.</p><p><strong>Authority</strong> rallies a shaken unit.</p></div><p>You have three orders each chapter. Correct math earns stronger results; repeated mistakes leave fewer resources for war and relief. Your math, government and battle performance lead to a Good, Normal or Bad ending.</p>${btn('Enter the Council','advance',false,'primary')}<details><summary>About history and the game</summary><p>${esc(text('history.compression_disclosure'))}</p></details></div>`;
 case 'chronicle':return `<div class="main frame">${this.plate(c.eventAssetId)}<div class="panel"><div class="eyebrow">${esc(text(c.dateStringId))}</div><h2>${esc(text(c.titleStringId))}</h2><p>${esc(text(c.chronicleStringId))}</p><p>${esc(chapterStories[s.chapterIndex-1].drama)}</p></div></div><aside class="rail frame"><h2>Chronicle</h2><p>Four chapters. Twelve orders. One decisive field.</p><p>Your choices can change the outcome.</p>${btn('Council','advance',false,'primary')}${btn('Replay scene','scene:ch'+s.chapterIndex)}${btn('Historical Method','history')}</aside>`;
 case 'council':return this.councilMarkup();
 case 'policy':return `<div class="wide frame scroll"><div class="eyebrow">COUNCIL POLICY · FREE · PICK ONE</div><h2>${esc(text(c.titleStringId))}</h2><div class="oc-grid pol">${c.policyChoices.map(p=>`<button class="oc" data-action="policy:${p.id}" ${!canPay(s,p.cost)?'disabled':''}>${familyIcon('govern')}<span class="oc-title">${esc(text(p.titleStringId))}</span>${costChips(p.cost)}${effectChips(this.effectSummary(p.effects))}</button>`).join('')}</div></div>`;
 case 'orders':return `<div class="main frame panel scroll"><div class="eyebrow">${icon('seal')} ${s.commandSeals} ORDER${s.commandSeals===1?'':'S'} LEFT THIS CHAPTER</div><h2>${esc(chapterStories[s.chapterIndex-1].title)}</h2><div class="tabs">${['all','govern','develop','diplomacy','march'].map(f=>`<button class="small" data-action="family:${f}" aria-selected="${this.family===f}">${f==='all'?'':icon(f)}${nice(f)}</button>`).join('')}</div><div class="oc-grid">${c.orderIds.filter(id=>this.family==='all'||order(id).family===this.family).map(id=>{const o=order(id),used=s.usedOrders.includes(id),ok=legalOrder(s,id);return `<button class="oc${used?' used':''}${!ok&&!used?' locked':''}" data-action="detail:${id}" ${used?'disabled':''}>${familyIcon(o.family)}<span class="oc-title">${esc(text(o.titleStringId))}</span>${tagRows(orderTags(id))}${costChips(o.cost,o.cost.mode==='entered_food')}${used?'<span class="stamp">Issued</span>':''}</button>`;}).join('')}</div></div>${this.adviserRail()}`;
 case 'administration':case 'world':case 'chapter_report':return chapterReport(this);
 case 'crisis':return this.crisisMarkup();
 case 'battle_review':return this.reviewMarkup();
 case 'convoy_briefing':return `<div class="main frame">${this.plate('EVENT_CONVOY')}<div class="panel"><h2>A wagon on the Tōkaidō</h2><p>A fictional escort encounter. Raiders are approaching a grain wagon. Protect it with two loaned formations; your main army is not at risk.</p></div></div><aside class="rail frame"><h2>Fund the escort</h2><p>30 Rice: ten escort rounds.<br>20 Materials: two ammunition charges.</p><p>${s.challengeRecords.some(c=>c.chapter===1&&c.path==='attempt1')?'Your first-try calculation earned one extra ammunition charge.':'A first-try answer among the opening two orders would add one ammunition charge.'}</p><p>Deliver intact: 60 Rice +4 Authority. Damaged: 30 Rice +2 Authority. Lost or skipped: no cargo. Unused paid ration packs return.</p><p>No Seal or math grade. Return to Chapter 1 with your remaining order.</p>${btn('Fund and escort','convoy:start',s.resources.food<30||s.resources.materials<20,'primary')}${btn('Skip encounter','convoy:skip')}${btn('Battle guide','battle-help')}</aside>`;
 case 'convoy_result':return `<div class="main frame">${this.plate('EVENT_CONVOY')}<div class="panel"><h2>Convoy ${nice(String(s.flags.convoy_status))}</h2><p>The escort returns to its garrison. Your main formations are unchanged; the resource receipt carries back into government.</p>${this.ledger(s.eventLog.filter(e=>['convoy.cargo','unused.rations.return'].includes(e.key)).slice(-3))}</div></div><aside class="rail frame"><h2>Return to council</h2><p>${s.commandSeals} Command Seal remains. No extra production, crisis, or world turn occurred.</p>${btn('Continue Chapter 1','advance',false,'primary')}${btn('Combat results','battle-ledger')}</aside>`;
 case 'battle_provision':return `<div class="wide frame scroll"><div class="eyebrow">BATTLE PREPARATION · 1 OF 2</div><h2>Provision the army</h2>${this.troopTable()}<p>Available: ${num(s.resources.food)} Rice + ${num(s.playerArmy.protectedBattleRice)} protected Rice. Protected stores are spent first.</p><label>Planned supplied rounds<select id="rounds">${Array.from({length:12},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===Math.max(1,Math.min(12,Math.floor((s.resources.food+s.playerArmy.protectedBattleRice)/battleQuota(s.playerArmy.formations.map(f=>f.troops)))))?'selected':''} ${n*battleQuota(s.playerArmy.formations.map(f=>f.troops))>s.resources.food+s.playerArmy.protectedBattleRice?'disabled':''}>${n} round${n===1?'':'s'}</option>`).join('')}</select></label>${btn('Calculate Supply','prepare-supply',s.resources.food+s.playerArmy.protectedBattleRice<battleQuota(s.playerArmy.formations.map(f=>f.troops)),'primary')}${btn('Depart without supplies','skip-supply',false,'danger')}${s.resources.food+s.playerArmy.protectedBattleRice<battleQuota(s.playerArmy.formations.map(f=>f.troops))?'<p class="loss">You cannot fund one full round. Recover supplies if possible, or explicitly depart unsupplied. No invalid calculation is required.</p>':''}</div>`;
 case 'battle_warchest':return `<div class="wide frame scroll"><div class="eyebrow">BATTLE PREPARATION · 2 OF 2</div><h2>Allocate the war chest</h2><p>Each equipment point costs ${rules.battle.equipmentCost} Treasury and gives +5% attack and defense. Each Volley charge costs ${rules.battle.ammoCost} Materials. You have ${num(s.resources.currency)} Treasury and ${num(s.resources.materials)} Materials: you will probably not afford everything, so choose what matters most.</p>${s.playerArmy.formations.map((f,i)=>`<label>${esc(text('formation.'+f.id))}<select id="equip${i}"><option value="0">No equipment</option><option value="1">1 point · ${rules.battle.equipmentCost} Treasury</option><option value="2">2 points · ${2*rules.battle.equipmentCost} Treasury</option></select></label>`).join('')}<label>Volley charges<select id="ammo">${Array.from({length:13},(_,n)=>n).map(n=>`<option value="${n}">${n} · ${n*rules.battle.ammoCost} Materials</option>`).join('')}</select></label>${btn('Check the Budget','prepare-chest',false,'primary')}</div>`;
 case 'battle_deployment':case 'battle_round':return this.battleMarkup();
 case 'battle_result':return `<div class="main frame">${this.plate('EVENT_CH4_MINO','large')}<div class="panel"><h2>${esc(nice(s.battle!.result!))}</h2><p>The battlefield is settled. The realm must now live with the campaign’s consequences.</p></div></div><aside class="rail frame"><h2>After the battle</h2><p>${s.battle!.formations.filter(f=>f.side==='east'&&!f.auxiliary).map(f=>`${text('formation.'+f.id)}: ${num(f.troops)} troops`).join('<br>')}</p>${btn('Read the Ending','advance',false,'primary')}${btn('Battle Ledger','battle-ledger')}</aside>`;
 case 'ending':{const e=endings.tiers.find(e=>e.tier===s.ending!.tier)!,result=s.battle?.result,lost=e.tier==='normal'&&result&&result!=='victory'?(result.includes('withdrawal')?'withdrawal':'defeat'):null,title=lost?'ending.'+lost+'.title':e.titleStringId,opening=lost?'ending.'+lost+'.opening':e.openingStringId;return `<div class="screen">${this.plate(e.assetId,'ending-plate')}<div class="ending-copy"><div class="eyebrow">${e.tier.toUpperCase()} ENDING · YOUR COUNTERFACTUAL CAMPAIGN</div><h2>${esc(text(title))}</h2><p>${esc(text(opening))}</p>${s.ending!.clauses.map(id=>`<p>${esc(text(id))}</p>`).join('')}${btn('Campaign Report','advance',false,'primary')}</div></div>`;}
 case 'campaign_report':return this.reportMarkup();
 default:return '';
 }}
 effectSummary(list:unknown[]){return list.flatMap(raw=>{const e=raw as Record<string,unknown>;if(typeof e.path==='string'&&typeof e.delta==='number'){const key=pathLabels[e.path]??'Realm strength';return /diplomacy|threats/.test(e.path)?[key+' '+(e.delta>0?'improves':'weakens')]:[key+': '+(e.delta>0?'+':'')+e.delta];}if(e.flag){const flags:Record<string,string>={famine_weight_relief_active:'Famine becomes less likely among possible crises',chapter2_route_supply_multiplier_per_thousand:'Field army food use rises 15% this chapter',main_force_tokaido:'Keep the main army on the Tōkaidō road',hidetada_delay_risk:'Divide your force between routes'};return flags[String(e.flag)]?[flags[String(e.flag)]]:[];}if(e.formationTroopsTotalDelta)return ['Soldiers: +'+e.formationTroopsTotalDelta];return [];}).join(' · ');}
 adviserRail(){const s=this.state!,p=pressure(s),band=p.total<25?'Low':p.total<50?'Guarded':p.total<75?'High':'Severe',need=mandatoryRice(s),k=s.diplomacy.kobayakawaCommitment,advice=realmAdvice(s).slice(0,2);return `<aside class="rail frame"><div class="rail-head"><img class="portrait" data-asset="PORTRAIT_IEYASU" src="./art/PORTRAIT_IEYASU.webp" alt="Ieyasu portrait"><div><div class="eyebrow">YOUR REALM</div><span class="chip">${icon('march')}Road: ${esc(nice(s.playerArmy.routeState))}</span></div></div>${miniMeter('Rice reserve',num(s.resources.food)+' · upkeep '+num(need),s.resources.food/(2*need)*100,s.resources.food<need?'bad':s.resources.food<2*need?'warn':'')}${miniMeter('Public order',s.edo.publicOrder+'/100',s.edo.publicOrder,s.edo.publicOrder<40?'bad':'')}${miniMeter('Kobayakawa '+k,kobaShort(rules.kobayakawa.bands,k),k,k<45?'bad':k<60?'warn':'good')}${miniMeter('Crisis risk',band+' · '+chance(p.total)/100+'%',p.total,p.total>=50?'bad':p.total>=25?'warn':'')}${s.chapterIndex>=2&&edoWatchTroops(s)>0?`<p class="rail-note warn-note">Edo defense ${s.edo.defense}: if you march now, ${num(edoWatchTroops(s))} soldiers must stay home to watch Uesugi.</p>`:''}${advice.map(t=>`<p class="rail-note">${esc(t)}</p>`).join('')}<details><summary>What raises crisis risk</summary><p>Rice ${p.ricePressurePoints}, Treasury ${p.treasuryPoints}, Authority ${p.authorityPoints}, public order ${p.publicOrderPoints}, infrastructure ${p.infrastructurePoints}, enemy ${p.enemy}, unresolved ${p.prior}.</p></details>${btn('How supplies help','forecast')}${btn('Future tactical plans','plan-guide')}${btn('View Map','map')}</aside>`;}
 councilMarkup(){const s=this.state!,f=forecast(s),story=chapterStories[s.chapterIndex-1];return `<div class="main frame">${this.plate('BG_COUNCIL','short')}<div class="panel"><div class="eyebrow">HONDA TADAKATSU · COUNCIL</div><h2>${esc(story.title)}</h2><p>${esc(story.drama)}</p><h3>Forecast for this chapter</h3><span class="chips">${resChip('food',f.rice,'+')}<span class="chip c-loss">${icon('food')}−${num(f.civilian+f.garrison+f.field)} Rice upkeep</span><span class="chip c-loss">${icon('currency')}−${num(f.wages)} Treasury wages</span></span><p class="muted small-note">Your orders can change this forecast.</p>${btn('Choose Policy','advance',false,'primary')}</div></div>${this.adviserRail()}`;}

 mapMarkup(){const s=this.state!,id=this.selectedNode in placeNames?this.selectedNode:'edo',ids=chapter(s.chapterIndex).orderIds,pins:Record<string,number>={};for(const [o,p] of Object.entries(orderPlaces))if(ids.includes(o)&&legalOrder(s,o))pins[p]=(pins[p]??0)+1;
  const at=s.playerArmy.locationId,plans:Record<number,string[]>={2:['edo','oyama'],3:['oyama','edo','kiyosu'],4:s.flags.gifu_controlled?['kiyosu','gifu','sekigahara']:['kiyosu','gifu','ogaki','sekigahara']},planned=plans[s.chapterIndex]?.[0]===at?plans[s.chapterIndex]:undefined;
  const tokens=stateTokens(s),here=tokens.filter(t=>t.place===id),orders=Object.entries(orderPlaces).filter(([o,p])=>p===id&&ids.includes(o)).map(([o])=>o);
  return `<div class="main frame"><div class="map-stage">${mapSvg({tokens,view:this.mapView,selected:id,pins,plannedRoute:planned,interactive:true})}<div class="map-legend"><i style="background:#5d8fc4"></i>East<i style="background:#c2513a"></i>West<i style="background:#d0a23a"></i>Undecided</div><div class="map-tools">${btn(this.mapView==='all'?'Mino close-up':'Whole map','map-zoom',false,'small')}${btn('Routes','routes',false,'small')}</div></div></div><aside class="rail frame"><div class="eyebrow">CAMPAIGN MAP · TAP A PLACE</div><h2>${esc(placeNames[id])}</h2><p>${esc(placeStatus(s,id))}</p>${here.map(t=>`<p><strong>${esc(t.label)}</strong>${t.strength?` · ${esc(t.strength)} troops`:''}<br>${esc(t.status)}</p>`).join('')}${orders.length?`<h3>Orders here</h3>${orders.map(o=>btn(text(order(o).titleStringId),'detail:'+o,s.phase!=='orders','small')).join('')}`:''}${planned?`<p>Next march: ${planned.map(p=>placeNames[p]).join(' → ')}, about ${planned.slice(1).reduce((t,b,k)=>t+(daysBetween(planned[k],b)??0),0)} days.</p>`:''}<p class="muted">${esc(strengthNote(s))}</p>${btn(s.phase==='council'?'Council':'Orders','orders')}</aside>`;}
 devSetupMarkup(){const o=this.devOptions,sel=(id:string,opts:[string,string][],v:string)=>`<select id="dev-${id}">${opts.map(([k,t])=>`<option value="${k}" ${k===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`,chk=(id:keyof DevOptions,t:string)=>`<label class="dev-check"><input type="checkbox" id="dev-${id}" ${o[id]?'checked':''}> ${esc(t)}</label>`;
  return `<div class="full-panel frame scroll dev-setup"><div class="eyebrow">OWNER PLAYTEST · SETUP</div><h2>DEV playtest</h2><p>Every calculation is answered for you, so you see the story, art, map and battles without doing the math. Nothing is saved and no records are made.</p>
  <label>Start at ${sel('start',Object.entries(devStartNames),o.start)}</label>
  <h3>Preparations</h3><div class="dev-grid">${chk('gifu','Gifu secured')}${chk('road','Tōkaidō repaired')}${chk('weatherScouts','Weather scouts paid')}${chk('hidetada','Hidetada marches by the Nakasendō')}${chk('ampleStores','Ample stores (Rice 1,500, Treasury 1,200, Materials 900)')}${chk('fullySupplied','Fully supplied army at the battle (12 rations, 2 equipment each, 12 ammunition)')}</div>
  <label>Kobayakawa ${sel('kobayakawa',Object.entries(kobaNames),o.kobayakawa)}</label>
  <label>Fieldworks ${sel('fieldworks',[['0','None'],['1','Tier 1'],['2','Tier 2']],String(o.fieldworks))}</label>
  <label>Scout information ${sel('scouts',[['exact','Exact numbers and plans (70)'],['estimates','Estimates (45)'],['none','Unknown (20)']],o.scouts)}</label>
  <h3>Story</h3>${chk('scenes','Play story scenes')}
  <p class="muted">Earlier chapters are played for you with sensible choices; your preparations are then applied. Later chapters can still change Kobayakawa and your stores.</p>
  <div class="row">${btn('Start','dev-start',false,'primary')}${btn('Battle Practice exercises','lab-config')}${btn('Settings','settings')}</div></div>`;}
 wireMap(){this.root.querySelectorAll<SVGGElement>('.geo-map [data-place]').forEach(g=>{const pick=()=>{this.selectedNode=g.dataset.place!;this.render();this.root.querySelector<SVGGElement>(`.geo-map [data-place="${this.selectedNode}"]`)?.focus();};g.addEventListener('click',pick);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick();}});});}
 openScene(scene:Scene){if(this.scene)return;if(this.aiTimer){clearTimeout(this.aiTimer);this.aiTimer=null;}this.scene=new ScenePlayer(this.root,this.state!,scene,{reduced:this.settings.reduced,onCue:id=>this.audio?.(id),onClose:()=>{this.scene=null;this.render();}});}
 /** Plays each story scene once per campaign, when its moment arrives (§3.1). */
 maybeScene(){const s=this.state;if(!s||this.view!=='play'||this.practicing||this.root.querySelector('dialog[open]'))return;const b=s.battle;let key='',scene:Scene|undefined;
  if(s.phase==='chronicle'){key='ch'+s.chapterIndex;scene=scenes[key];}
  else if(s.phase==='battle_deployment'&&b?.scenarioId==='sekigahara'){key='dawn';scene=scenes.dawn;}
  else if(s.phase==='battle_round'&&b?.scenarioId==='sekigahara'&&b.dispatchPending&&b.auxSide){const entered=b.formations.some(f=>f.id==='aux_kobayakawa');key='koba:'+b.round;scene=b.auxSide==='inactive'?scenes.koba_hold:entered?scenes['koba_'+b.auxSide]:{title:'Kobayakawa’s choice',task:'Read the coalition dispatch, then continue the battle.',beats:[{art:'BAT-KOBA1',pan:'in',caption:b.auxSide==='east'?`Kobayakawa’s banners stir on Matsuo hill. He will come down on your side, but not before round ${b.auxEntryRound}.`:`Kobayakawa’s banners stir on Matsuo hill. He has chosen Ishida, and will attack at round ${b.auxEntryRound}.`,speaker:{name:'Kobayakawa Hideaki',portrait:'PORTRAIT_KOBAYAKAWA'}}]};}
  else if(s.phase==='world'){key='west'+s.chapterIndex;scene=this.westScene();}
  else if(s.phase==='ending'&&s.ending){const e=endings.tiers.find(t=>t.tier===s.ending!.tier)!,r=b?.result,lost=e.tier==='normal'&&r&&r!=='victory'?(r.includes('withdrawal')?'withdrawal':'defeat'):null;key='ending';scene=endingScene(s,text(lost?'ending.'+lost+'.title':e.titleStringId));}
  else if(s.phase==='battle_round'&&b?.scenarioId==='sekigahara'&&!this.settings.skipAnimation){const broke=this.lastEvents.find(e=>e.type==='FORMATION_ROUTED'||e.type==='FORMATION_SHATTERED');const camp=(['east','west'] as const).find(side=>b.campChecks[side]>0);
   if(broke){const f=b.formations.find(f=>f.id===broke.key);if(f){key='rout:'+b.round+':'+f.id+':'+broke.type;const name=text('formation.'+f.id);scene={title:f.side==='east'?'Your line breaks':'The Western line breaks',task:'Continue the battle.',beats:[{art:'BAT-ROUT',pan:'out',caption:broke.type==='FORMATION_SHATTERED'?`${name} is shattered and leaves the field.`:`${name} breaks and falls back. A nearby formation may rally it.`,speaker:{name,portrait:'PORTRAIT_'+portraitFor(f.id)}}]};}}
   else if(camp){key='camp:'+camp+':'+b.round+':'+b.campChecks[camp];scene={title:'The camp',task:camp==='east'?'Hold the Western camp through one more check to win.':'Retake your camp before the next check, or the battle is lost.',beats:[{art:'BAT-CAMP',pan:'in',caption:camp==='east'?`Your banner flies over the Western camp: check ${b.campChecks.east} of 2.`:`A Western banner flies over your camp: check ${b.campChecks.west} of 2.`}]};}}
  if(!scene||this.devRun&&!this.devOptions.scenes)return;const id=s.seed+':'+key;if(this.seenScenes.has(id))return;this.seenScenes.add(id);if(!this.devRun)saveSeen(this.seenScenes);this.openScene(scene);}
 westScene():Scene{const s=this.state!,acts=this.lastEvents.filter(e=>e.type==='AI_ACTION_TAKEN'),letters=this.lastEvents.some(e=>e.type==='ISHIDA_LETTERS');
  const lines=acts.map(e=>aiStories[e.key]?.title).filter(Boolean) as string[];if(letters)lines.push('Ishida writes again to Kobayakawa');
  const beats:Beat[]=[{art:'BAT-WEST',pan:'in',caption:lines.length?`At Ōgaki, Ishida’s council decides: ${lines.join('; ')}.`:'At Ōgaki, Ishida’s council plans its next move.',speaker:{name:'Ishida Mitsunari',portrait:'PORTRAIT_ISHIDA'}}];
  const where:Record<string,string>={ai_fortify_gifu:'gifu',ai_fortify_ogaki:'ogaki',ai_raise_troops:'ogaki',ai_pressure_kiyosu:'kiyosu',ai_influence_kobayakawa:'matsuo',ai_depot_raid:'edo',ai_buy_rice:'ogaki'};const notes=acts.filter(e=>where[e.key]).map(e=>`${placeNames[where[e.key]]}: ${(aiStories[e.key]?.title??'').replace(/^The West /,'the West ').replace(/^Western /,'western ').replace(/^New /,'new ').replace(/^Ogaki /,'Ōgaki ')}`);const places=[...new Set(acts.map(e=>where[e.key]).filter(Boolean))];if(letters){if(!places.includes('matsuo'))places.push('matsuo');notes.push('Matsuo hill: Ishida’s letters reach Kobayakawa');}
  if(places.length)beats.push({caption:notes.join('. ')+'.',map:{view:places.every(p=>['gifu','ogaki','matsuo','sekigahara','kiyosu'].includes(p))&&s.chapterIndex>=3?'minoWide':'all',tokens:'state',steps:[{wait:400},{highlight:places}]}});
  return {title:'The Western council',task:'Read the dispatch below, then review the chapter.',beats};}

 ledger(events:State['eventLog']){return friendlyLedger(this,events);}
 detail(id:string){const s=this.state!,o=order(id),story=orderStories[id];this.modal(text(o.titleStringId),`<p class="lead">${esc(story.why)}</p><div class="dl-grid"><div class="dl-box gain"><h3>${icon('check')} You get</h3>${tagRows(orderTags(id))}<p>${esc(story.payoff)}</p></div><div class="dl-box"><h3>${icon('seal')} It costs</h3>${costChips(o.cost,o.cost.mode==='entered_food')}<span class="chips"><span class="chip">${icon('seal')}1 order</span></span></div></div><p class="muted small-note">${esc(story.tradeoff)}</p><details><summary>Math and rewards</summary><p>${esc(template(o.challengeTemplateId).skillTags.map(nice).join(' · '))}</p><p>${purchasedTemplate(o.challengeTemplateId)?'A correct or adviser-assisted purchase delivers all funded rations. Planning dividends are 10%, 5%, 2%, then 0% for adviser help.':(o.precisionMode==='refund_primary_cost'?'A correct first answer completes the order and saves 10% of its main cost.':'A correct first answer earns 10% more benefit.')+' Correct second and third answers earn 85% and 65% of the normal benefit; adviser help earns 50%.'}</p></details>${!legalOrder(s,id)?'<p class="loss">You need more available orders, resources or alliance support to issue this order.</p>':''}<div class="row">${btn('Plan this order','open:'+id,!legalOrder(s,id),'primary')}${btn('Back','close')}</div>`);}
 mathModal(){const c=this.state!.activeOrder!;this.modal(c.context==='order'?text(order(c.orderId).titleStringId):c.context==='crisis'?'Prepare the relief order':c.context==='provision'?'Provision the army':'Balance the war chest',calculationMarkup(this),()=>{this.root.querySelector('dialog')?.classList.add('math-dialog');this.root.querySelectorAll<HTMLInputElement>('[data-answer]').forEach(input=>input.addEventListener('keydown',e=>{if(e.key==='Enter'&&c.attempts<ATTEMPT_LIMIT&&!c.adviserShown){e.preventDefault();void this.action('answer');}}));});}
 resultModal(){this.modal(this.state!.challengeRecords.at(-1)!.path==='attempt1'?'Accurate planning':'Your order’s result',orderResultMarkup(this));}
 auditModal(){this.modal('Recover audited stores',`<p>${esc(pathNames[this.state!.challengeRecords.at(-1)!.path])}. ${this.state!.pendingReward===1100?'Accurate planning earned 10% extra stores.':'Your recovery reflects the attempts and help used.'}</p><p>Choose which resource to recover. The amount goes straight into your stores.</p>${(['food','currency','materials'] as const).map(r=>btn(labelResource(r)+' +'+Math.round(order('audit_stores').rewardOptions![r]*this.state!.pendingReward!/1000),'audit:'+r)).join('')}`);}
 crisisMarkup(){const s=this.state!,cr=currentCrisis(s)!,t=crisisType(cr.id);return `<div class="main frame">${this.plate(t.eventAssetId)}<div class="panel"><div class="eyebrow">SEVERITY ${cr.severity} · ${cr.pressure<50?'LOCAL':'MAJOR'} DISRUPTION</div><h2>${esc(text(t.titleStringId))}</h2><p>${cr.id==='flood'?'Rain has overwhelmed vulnerable roads and embankments.':cr.id==='plague'?'Illness is spreading along crowded travel routes.':'Disruption has reached the districts.'} Your reserves determine what the administration can protect.</p></div></div><aside class="rail frame"><h2>Choose a response</h2>${(['full','partial','accept'] as const).map(r=>{const cost=crisisCost(cr,r),ok=canPay(s,cost);return `<h3>${nice(r)} mitigation</h3><p>${esc(costLine(cost))}</p>${!ok?`<p class="loss">Missing ${Object.entries(cost).filter(([k,v])=>(v??0)>s.resources[k as Resource]).map(([k,v])=>`${(v??0)-s.resources[k as Resource]} ${labelResource(k)}`).join(', ')}</p>`:''}${btn(r==='accept'?'Accept the Loss':nice(r)+' Response','crisis:'+r,!ok)}${!ok?(['currency','materials'] as Resource[]).map(resource=>{try{const cost2=emergencyCost(s,cost,resource);return canPay(s,cost2)?btn('Use Authority','emergency:'+r+':'+resource):'';}catch{return '';}}).join(''):''}`;}).join('')}</aside>`;}
 troopTable(){return `<table class="ledger"><tr><th>Formation</th><th>Troops</th></tr>${this.state!.playerArmy.formations.map(f=>`<tr><td>${esc(text('formation.'+f.id))}</td><td>${num(f.troops)}</td></tr>`).join('')}</table><p class="muted">These soldier counts are simplified for play. More soldiers increase combat strength and the Rice needed each round.</p>`;}
 reviewMarkup(){const s=this.state!,k=s.diplomacy.kobayakawaCommitment;return `<div class="wide frame scroll"><div class="eyebrow">SEKIGAHARA · THE BATTLE IS NEXT</div><h2>Your decisions reach the field</h2><p>Three units, two actions each per turn. Win by holding the enemy camp for two round ends, or by forcing its three main units to retreat.</p><span class="chips">${s.playerArmy.formations.map(f=>`<span class="chip">${esc(text('formation.'+f.id))} · ${num(f.troops)}</span>`).join('')}</span><div class="facts">${factTile(s.playerArmy.readiness>=60,'Readiness '+s.playerArmy.readiness+'/100','Higher readiness means better starting morale')}${factTile(s.playerArmy.routeState==='prepared','Road '+(s.playerArmy.routeState==='prepared'?'repaired':'not repaired'),s.playerArmy.routeState==='prepared'?'Your army acts earlier in round 1':'No opening initiative bonus')}${(()=>{const w=s.eventLog.find(e=>e.type==='EDO_WATCH');return factTile(!w,w?`${num(Number(w.detail?.troops))} soldiers guard Edo`:'Edo secure',w?'Edo’s walls were too weak to leave unguarded':'Every soldier marches to Sekigahara');})()}${factTile(!!s.flags.gifu_controlled,'Gifu '+(s.flags.gifu_controlled?'taken':'held by the West'),s.flags.gifu_controlled?'Deploy in columns 1 and 2':'Deploy only in column 1')}${factTile(s.playerArmy.fieldworkTier>0,s.playerArmy.fieldworkTier+' defensive positions','Prepared squares protect a unit')}${factTile(s.resources.authority>=10,'Authority '+s.resources.authority,'Keep 10 for a Rally in battle')}${factTile(k>=60,'Kobayakawa '+k,kobaShort(rules.kobayakawa.bands,k))}${factTile(this.cohesionBand()!=='Fractured','Alliance '+this.cohesionBand(),'Unity steadies your allies')}${factTile(!!s.flags.weather_scouted,s.flags.weather_scouted?'Rain scouted':'Rain not scouted',s.flags.weather_scouted?'Gunners ready for the opening rain':'Weaker Volleys in round 1')}${factTile(s.playerArmy.protectedBattleRice>0,num(s.playerArmy.protectedBattleRice)+' Rice protected','Saved for battle rations')}</div><p>Next: feed the army and buy equipment and ammunition.</p>${btn('Pack battle rations','advance',false,'primary')}${btn('Read the battle guide','battle-help')}</div>`;}
 cohesionBand(){const n=this.state!.diplomacy.coalitionCohesion;return ['Fractured','Uneasy','Steady','United','Resolute'][Math.min(4,Math.floor(n/20))];}
 commitmentBand(){const n=this.state!.diplomacy.kobayakawaCommitment;return n<40?'Opposed':n<70?'Uncertain':'Committed';}
 battleMarkup(){return battleMarkup(this);}
 reportMarkup(){return campaignReport(this);}
 savesMarkup(){return `<div class="full-panel frame"><div class="eyebrow">LOCAL CAMPAIGNS</div><h2>Save and Load</h2><p class="storage-info">${esc(storageNotice()||'Save slots use this viewer’s local database. Export portable backups before changing apps or moving files.')}</p><div class="order-list">${(['autosave','manual-1','manual-2','manual-3'] as Slot[]).map(slot=>{const e=this.slots[slot];return `<div class="frame panel"><h3>${esc(e?.slotLabel??nice(slot))}</h3><p>${e?'Chapter '+e.state?.chapterIndex+' · '+esc(e.savedAt):'Empty'}</p><div class="row">${btn('Load','load:'+slot,!e)}${slot!=='autosave'?btn('Save','save:'+slot,!this.state||this.practicing||!safeSave(this.state)):''}${btn('Export','export:'+slot,!e)}${slot!=='autosave'?btn('Rename','rename:'+slot,!e)+btn('Delete','delete:'+slot,!e):''}</div></div>`;}).join('')}</div><label>Import a campaign<input type="file" id="import" accept=".json,.mcsave.json"></label>${btn('Import to Slot 3','import')}<details><summary>Import copied save text</summary><label>Paste the entire exported save<textarea id="import-text" rows="6" spellcheck="false"></textarea></label>${btn('Import pasted save to Slot 3','import-paste')}</details>${btn('Export legacy backups','legacy-backups')}${btn('Export Current','export-current',!this.state||this.practicing)}${btn('Return','back')}</div>`;}
 settingsMarkup(){return `<div class="full-panel frame"><h2>Settings</h2><div class="grid2"><label>Music<input id="music" type="range" min="0" max="100" value="${this.settings.music}"></label><label>Effects<input id="effects" type="range" min="0" max="100" value="${this.settings.effects}"></label></div>${(['muted','reduced','large','legible','skipAnimation'] as const).map(k=>`<label><input type="checkbox" id="${k}" style="display:inline;width:auto" ${this.settings[k]?'checked':''}> ${k==='muted'?'Mute':k==='reduced'?'Reduced motion':k==='large'?'Large text':k==='legible'?'High legibility':'Skip combat pauses'}</label>`).join('')}<div class="row">${btn('Apply','apply-settings',false,'primary')}${btn('Fullscreen','fullscreen')}${btn('Return','back')}</div><h3>Practice the battle</h3><p>Test deployment, attacks and supplies without playing the campaign first.</p>${btn('Open Battle Practice / DEV','lab-config')}<h3>iPhone / iPad compatibility</h3><p>Phone layout supports portrait and landscape. Swipe the battlefield sideways for all columns. Local HTML viewers must run JavaScript, not just preview source. If saving is session-only, export or copy a backup before closing. File sharing and pasted-save import are available in Save / Load.</p><h3>Install the web edition</h3><p>Open the HTTPS version in Safari, then Share → Add to Home Screen. Wait for “Ready for offline play” before disconnecting. Play in landscape.</p></div>`;}
 async action(id:string){const [kind,value,extra]=id.split(':');const s=this.state;try{
 switch(kind){
 case 'lab-config':if(__DEV_BUILD__||this.teacherLock.unlocked||this.practicing)this.enterLab();else this.modal('Teacher password',`<p>Battle Practice lets you set up any battle without the campaign. Enter the teacher password to open it.</p><label>Password <input id="teacher-password" type="password" autocomplete="off"></label><p id="teacher-notice" class="loss" role="alert"></p><div class="row">${btn('Unlock','teacher-unlock',false,'primary')}${btn('Cancel','close')}</div>`,()=>this.root.querySelector<HTMLInputElement>('#teacher-password')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();this.action('teacher-unlock');}}));break;
 case 'teacher-unlock':{const input=this.root.querySelector<HTMLInputElement>('#teacher-password');const error=await this.teacherLock.unlock(input?.value??'');if(error){const n=this.root.querySelector('#teacher-notice');if(n)n.textContent=error;if(input){input.value='';input.focus();}}else{this.root.querySelector('dialog')?.remove();this.enterLab();}break;}
 case 'teacher-change':this.modal('Change teacher password',`<p>The new password is stored only on this device.</p><label>New password <input id="teacher-new" type="password" autocomplete="new-password"></label><p id="teacher-notice" class="loss" role="alert"></p><div class="row">${btn('Save','teacher-save',false,'primary')}${btn('Cancel','close')}</div>`);break;
 case 'teacher-save':{const v=this.root.querySelector<HTMLInputElement>('#teacher-new')?.value??'';try{await this.teacherLock.change(v);this.root.querySelector('dialog')?.remove();this.message('Teacher password changed on this device.');}catch(e){const n=this.root.querySelector('#teacher-notice');if(n)n.textContent=(e as Error).message;}break;}
 case 'phone-board':this.root.querySelector('.battle-viewport')?.scrollIntoView?.({block:'start',behavior:this.settings.reduced?'auto':'smooth'});break;
 case 'phone-commands':this.root.querySelector('.battle-rail')?.scrollIntoView?.({block:'start',behavior:this.settings.reduced?'auto':'smooth'});break;
 case 'lab-start':{const input=(key:string)=>(this.root.querySelector('#lab-'+key) as HTMLInputElement);const next={...this.labOptions,preset:input('preset').value as BattleLabOptions['preset'],gifu:input('gifu').checked,automaticEnemy:input('automaticEnemy').checked};for(const k of ['supply','enemySupply','ammo','enemyAmmo','authority','equipment','morale','fieldworks','ally'] as const)next[k]=Number(input(k).value);createBattleLab(next);this.labOptions=next;this.startLab();break;}
 case 'lab-restart':this.startLab();break;
 case 'lab-exit':this.exitLab();break;
 case 'lab-enemy':if(this.practicing&&s?.phase==='battle_round'&&activeUnit(s)?.side==='west')this.dispatch({type:'AI_TURN'});break;
 case 'new':if(s&&s.phase!=='campaign_report')return this.confirm('Begin another campaign?','Your current in-memory campaign will be replaced. Saved slots remain available.',()=>{this.view='setup';this.render();});this.view='setup';this.render();break;
 case 'start':{const value=(this.root.querySelector('#seed') as HTMLInputElement).value.trim().toUpperCase();if(value&&(!/^[0-9A-V]{1,8}$/.test(value)||parseInt(value,32)>4294967295))return this.message('Check the campaign code. It uses up to eight characters: 0–9 and A–V. Or leave it blank.');const mode=(this.root.querySelector('#mode') as HTMLSelectElement).value as State['mode'];this.labReturn=null;this.state=createState(value?parseInt(value,32):typeof globalThis.crypto?.getRandomValues==='function'?crypto.getRandomValues(new Uint32Array(1))[0]:Date.now()>>>0,mode,new Date().toISOString());this.view='play';this.tab='Realm';this.render();await this.save('autosave');break;}
 case 'continue':case 'load':this.state=await loadSlot((value??'autosave') as Slot);this.labReturn=null;this.view='play';this.tab='Realm';this.render();break;
 case 'title':this.view='title';this.render();break;
 case 'saves':case 'settings':case 'history':case 'credits':this.view=kind;this.render();break;
 case 'back':this.view=this.state?'play':'title';this.render();break;
 case 'advance':this.tab='Realm';this.dispatch({type:'ADVANCE'});break;
 case 'map':this.tab='Map';if(['council','orders'].includes(s?.phase??''))this.render();else this.message('Map orders are available during the council and orders phases.');break;
 case 'orders':this.tab='Realm';this.render();break;
 case 'node':this.selectedNode=value;this.render();break;
 case 'dev-setup':if(this.scene)this.scene.close();this.closeModal();this.view='dev-setup';this.state=null;this.render();break;
 case 'dev-start':{const v=(id:string)=>(this.root.querySelector('#dev-'+id) as HTMLInputElement|HTMLSelectElement);const c=(id:string)=>(this.root.querySelector('#dev-'+id) as HTMLInputElement).checked;
  this.devOptions={start:v('start').value as DevOptions['start'],scenes:c('scenes'),gifu:c('gifu'),road:c('road'),weatherScouts:c('weatherScouts'),fieldworks:Number(v('fieldworks').value) as 0|1|2,kobayakawa:v('kobayakawa').value as DevOptions['kobayakawa'],scouts:v('scouts').value as DevOptions['scouts'],hidetada:c('hidetada'),ampleStores:c('ampleStores'),fullySupplied:c('fullySupplied')};saveDev(this.devOptions);
  try{const seed=typeof globalThis.crypto?.getRandomValues==='function'?crypto.getRandomValues(new Uint32Array(1))[0]:Date.now()>>>0;this.state=devStart(this.devOptions,seed);}catch(e){this.message(String((e as Error).message??e));break;}
  this.lastEvents=[];this.view='play';this.tab='Realm';this.selectedUnit='east_ii';this.render();break;}
 case 'dev-gallery':{const s2=this.state;const list:[string,string][]=[['ch1','Chapter 1 scene'],['ch2','Chapter 2 scene'],['ch3','Chapter 3 scene'],['ch4','Chapter 4 scene (branch follows Gifu)'],['dawn','Sekigahara dawn'],['koba_east','Kobayakawa joins you'],['koba_west','Kobayakawa turns on you'],['koba_hold','Kobayakawa holds'],['west','Western council']];
  this.modal('Scene gallery',`<p class="muted">Replays any story scene with the current campaign’s choices. Battle-only scenes (routs, camp checks, ending montage) play during the battle.</p><div class="order-list">${list.map(([k,t])=>btn(t,'dev-scene:'+k)).join('')}</div>${btn('Close','close')}`);void s2;break;}
 case 'dev-scene':{this.root.querySelector('dialog')?.remove();const sc=scenes[value];if(sc)this.openScene(sc);break;}
 case 'scene':{const sc=scenes[value];if(sc)this.openScene(sc);break;}
 case 'map-zoom':this.mapView=this.mapView==='all'?'mino':'all';{const svg=this.root.querySelector<SVGSVGElement>('.geo-map');if(svg)void zoomTo(svg,this.mapView,900,this.settings.reduced);const b=this.root.querySelector('[data-action="map-zoom"]');if(b)b.textContent=this.mapView==='all'?'Mino close-up':'Whole map';}break;
 case 'enemy-next':this.enemyGo=true;this.render();break;
 case 'enemy-pause':this.enemyPaused=!this.enemyPaused;this.render();break;
 case 'ring-close':this.ringOpen=false;this.render();break;
 case 'ring':this.ringOpen=false;if(['defend','brace','forced_step','end'].includes(value)||!s)this.tactic(value);else{this.tactic(value);if(this.battleMode===value)this.render();}break;
 case 'battle-confirm':{const pb=this.pendingBattle;this.pendingBattle=null;this.root.querySelector('dialog')?.remove();if(pb)this.dispatch({type:'BATTLE',id:pb.id,action:pb.action});break;}
 case 'battle-more':{const b=s?.battle;this.modal('Battle options',`<div class="order-list">${btn('Enemy plans','intents')}${btn('How to play','battle-help')}${btn('Combat results','battle-ledger')}${b?.reviewSeen?btn('Battle council','council:open'):''}${s?.phase==='battle_round'?btn('Withdraw','withdraw',false,'danger'):''}</div>${btn('Close','close')}`);break;}
 case 'family':this.family=value;this.render();break;
 case 'policy':this.dispatch({type:'POLICY',id:value});break;
 case 'detail':this.detail(value);break;
 case 'open':this.dispatch({type:'OPEN_ORDER',id:value,now:Date.now()});break;
 case 'answer':{const c=s?.activeOrder;if(!c||c.attempts>=ATTEMPT_LIMIT||c.adviserShown)return;const answer:Answer={};this.root.querySelectorAll<HTMLInputElement|HTMLSelectElement>('[data-answer]').forEach(i=>answer[i.dataset.answer!]=i.value);if(c.fields.some(k=>typeof c.answer[k]==='number'&&literal(answer[k])===null||answer[k]===''))return this.message('Enter a number, decimal, simple fraction, or plan in every field. Invalid notation spends no attempt.');const command:Command={type:'ANSWER',answer,now:Date.now()};if(!c.attempts&&c.context==='order')this.confirm('Issue this order?','Submitting spends one Command Seal. Fixed costs commit now; calculated Rice is paid only when you confirm a valid or explicit unchecked plan. Production and upkeep follow at chapter end.',()=>this.dispatch(command));else this.dispatch(command);break;}
 case 'symbol':{const field=this.root.querySelector<HTMLInputElement>(`[data-answer="${value}"]`);if(field&&!field.disabled){const at=field.selectionStart??field.value.length,mark=extra==='fraction'?'/':'.';field.setRangeText(mark,at,field.selectionEnd??at,'end');field.focus();}break;}
 case 'hint':this.dispatch({type:'HINT'});break;
 case 'adviser':this.dispatch({type:'ADVISER'});break;
 case 'complete':{if(value==='adviser'){this.dispatch({type:'COMPLETE',path:'adviser',now:Date.now()});break;}const answer:Answer={};this.root.querySelectorAll<HTMLInputElement|HTMLSelectElement>('[data-answer]').forEach(i=>answer[i.dataset.answer!]=i.value);let copy='The current entry fields will be used without mastery or a planning dividend. Resource and labor limits still apply.';const c=s!.activeOrder!;if(value==='proceedEstimate'&&(c.context==='provision'||c.operands.issuedRations)){const budget=exactWhole(answer.rice);if(budget===null||budget<0)return this.message('Edit Rice to an explicit nonnegative whole amount, then choose unchecked again. This correction spends no attempt.');const quota=c.context==='provision'?battleQuota(s!.playerArmy.formations.map(f=>f.troops)):(c.operands.issuedRations as number[]).reduce((a,b)=>a+b,0),packs=Math.min(c.context==='provision'?12:Number.MAX_SAFE_INTEGER,Math.floor(budget/quota)),cost=packs*quota,protectedRice=c.context==='provision'?Math.min(cost,s!.playerArmy.protectedBattleRice):0;copy=`Your unchecked budget is ${budget} Rice. Pack ${packs} full periods for ${cost} Rice: ${protectedRice} protected + ${cost-protectedRice} newly paid. ${budget-cost} from your stated budget remains unspent. No mastery or dividend.`;}this.confirm(value==='abandon'?'Cancel this order?':'Confirm unchecked spend?',value==='abandon'?'The Seal stays spent. Recover 75% of costs already committed; uncommitted Rice was never charged.':copy,()=>this.dispatch({type:'COMPLETE',path:value as 'abandon'|'proceedEstimate',answer,now:Date.now()}));break;}
 case 'close':this.closeModal();break;
 case 'close-result':this.root.querySelector('dialog')?.remove();if(s?.pendingReward!==null&&s?.pendingReward!==undefined)this.auditModal();else this.render();break;
 case 'audit':this.dispatch({type:'AUDIT_REWARD',resource:value as 'food'|'currency'|'materials'});break;
 case 'end':this.dispatch({type:'END_CHAPTER'});break;
 case 'forfeit':this.confirm('Forfeit unused Seals?','No legal order remains. The remaining Seals will be spent with no reward. The chapter’s usual consequences still resolve.',()=>this.dispatch({type:'FORFEIT_SEALS'}));break;
 case 'crisis':case 'emergency':this.confirm('Resolve this response?',kind==='emergency'?'Spend 10 additional Authority to substitute missing Treasury or Materials. This is available only once per campaign.':'The displayed cost is committed and the crisis consequences will follow.',()=>this.dispatch({type:'CRISIS_RESPONSE',response:value as 'full'|'partial'|'accept',emergency:extra as Resource|undefined,now:Date.now()}));break;
 case 'convoy':this.confirm(value==='start'?'Fund the escort?':'Skip the escort?',value==='start'?'Spend 30 Rice and 20 Materials. Cargo delivery is not guaranteed. No Seal is spent.':'No supplies are charged and no cargo is awarded. Continue with your remaining Chapter 1 order.',()=>this.dispatch({type:'CONVOY',start:value==='start'}));break;
 case 'plans':this.modal('Tactical plan',planMarkup(this));break;
 case 'plan-guide':this.modal('Campaign-earned tactical plans','<article class="plan-card"><h3>Flanking Detachment</h3><p>Prepare or restore the road and secure Gifu. Choose a northern or southern entry for one Round 3 reserve. Only two formations start on the field.</p></article><article class="plan-card"><h3>Engineer Detachment</h3><p>Fund Fieldworks in Chapter 4. Exchange the placed defenses for a spear engineer who can build one shared southern crossing.</p></article><article class="plan-card"><h3>Fire Discipline</h3><p>Buy equipment for Kuroda’s Gunners before the finale. Suppress exchanges damage and ammunition for control.</p></article><p>Choose one after funding the war chest. Standard Line is always available. Scouting additionally reveals precise enemy intentions.</p>'+btn('Return','close'));break;
 case 'plan':{const reserve=this.root.querySelector<HTMLSelectElement>('#reserve')?.value;this.dispatch({type:'PLAN',plan:value as TacticalPlan,reserve,entry:this.root.querySelector<HTMLSelectElement>('#reserve-entry')?.value as 'north'|'south'|undefined});break;}
 case 'council':if(value==='accept')this.confirm('Accept the current score?','The battle ends immediately using the displayed scores. Your unused paid packs return.',()=>this.dispatch({type:'BATTLE_COUNCIL',choice:'accept'}));else this.dispatch({type:'BATTLE_COUNCIL',choice:value as 'open'|'continue'});break;
 case 'intents':this.modal('Enemy intentions',`<p class="muted">${esc(intelNote(s!))}</p>`+(intelLevel(s!)==='none'&&!s!.flags.weather_scouted?'<p>Your scouts cannot read the Western plans. Raise Scout information during the campaign, or pay for weather scouts, to see them.</p>':Object.values(s!.battle!.intents).filter(i=>alive(s!.battle!.formations.find(f=>f.id===i.unitId)!)).map(i=>`<article class="dispatch-note"><h3>${esc(text('formation.'+i.unitId))}</h3><p>${esc(i.goal)}</p>${committedActionVisible(s!)?`<p>Scouted committed action: ${esc(commandNames[i.action.kind]??nice(i.action.kind))}${'target' in i.action?' → '+esc(text('formation.'+i.action.target)):'point' in i.action?` → column ${i.action.point.x+1}, row ${i.action.point.y+1}`:''}</p>`:'<p>Broad intention only. Weather scouts, or Scout information of '+rules.intelligence.precise+' or more, reveal the committed next command.</p>'}${i.reason?`<p class="muted">${esc(i.reason)}</p>`:''}</article>`).join(''))+btn('Return','close'));break;
 case 'resupply':{const n=Number(value),u=activeUnit(s!)!;this.confirm('Buy future rations?',`${n} future packs cost ${n*s!.battle!.quota.east} uncommitted Rice. No dividend. This round’s supply status stays unchanged. One resupply per army.`,()=>this.dispatch({type:'BATTLE',id:u.id,action:{kind:'resupply',rounds:n}}));break;}
 case 'skip-supply':this.confirm('Depart without supplies?','Every unsupplied round costs each formation '+rules.battle.unsuppliedMoraleLoss+' morale and weakens its attacks. An army that starts unsupplied almost always loses. You may resupply once at your camp if Rice is available. No math grade is added.',()=>this.dispatch({type:'SKIP_PROVISION'}));break;
 case 'prepare-supply':this.dispatch({type:'PREP_PROVISION',rounds:Number((this.root.querySelector('#rounds') as HTMLSelectElement).value),now:Date.now()});break;
 case 'prepare-chest':{const cmd:Command={type:'PREP_WARCHEST',equipment:[0,1,2].map(i=>Number((this.root.querySelector('#equip'+i) as HTMLSelectElement).value)),ammo:Number((this.root.querySelector('#ammo') as HTMLSelectElement).value),now:Date.now()};if(cmd.type==='PREP_WARCHEST'&&cmd.ammo===0)this.confirm('Depart with no ammunition?','Without Volley charges your gunners cannot fire at range or suppress the enemy. Battles fought without ammunition are usually lost or drawn out. Even three charges make a large difference.',()=>this.dispatch(cmd));else this.dispatch(cmd);break;}
 case 'select-unit':this.selectedUnit=value;this.render();break;
 case 'tile':this.tile({x:Number(value),y:Number(extra)});break;
 case 'begin-battle':this.confirm('Begin Sekigahara?','Deployment will close. Your committed supplies, equipment, and coalition choices now govern the battle.',()=>this.dispatch({type:'BEGIN_BATTLE'}));break;
 case 'tactic':this.tactic(value);break;
 case 'withdraw':this.confirm('Withdraw the army?','With two un-routed supplied core formations, withdrawal is orderly. Otherwise the retreat is disordered. This ends the battle.',()=>this.dispatch({type:'WITHDRAW'}));break;
 case 'battle-help':this.modal('How to command the battle',battleHelp());break;
 case 'battle-ledger':this.modal('Battle ledger',`<div class="scroll" style="max-height:270px">${s!.eventLog.filter(e=>e.type==='COMBAT_RESOLVED').map(e=>`<p>${esc(text('formation.'+e.detail!.attackerId))} → ${esc(text('formation.'+e.detail!.defenderId))}<br>Losses: attacker ${e.detail!.attackerLoss}, defender ${e.detail!.defenderLoss} · morale ${e.detail!.attackerMoraleLoss} / ${e.detail!.defenderMoraleLoss}</p>`).join('')}</div>`+btn('Return','close'));break;
 case 'forecast':case 'resource':{const f=forecast(s!),p=pressure(s!);this.modal('Your stores and the coming battle',`<p><strong>Rice</strong> feeds households and soldiers now, and buys supplied rounds in battle.</p><p><strong>Treasury</strong> pays wages and buys equipment: ${rules.battle.equipmentCost} per equipment point, for +5% attack and defense.</p><p><strong>Materials</strong> build defenses and buy ammunition: ${rules.battle.ammoCost} for each Volley charge.</p><p><strong>Authority</strong> supports morale and funds Rally: 10 to restore 15 morale to one unit.</p><h3>Next chapter settlement</h3><p>Expected production: ${num(f.rice)} Rice, ${num(f.treasury)} Treasury and ${num(f.materials)} Materials.</p><p>Expected upkeep: ${num(f.civilian+f.garrison+f.field)} Rice and ${num(f.wages)} Treasury in wages. Packed march rations can cover the field army’s share.</p><p>Current disruption risk: ${chance(p.total)/100}%. Low stores and disorder make the realm more vulnerable and leave less to spend on relief.</p><details><summary>How the figures are calculated</summary><p>Rice: civilians ${f.civilian}, garrison ${f.garrison}, field army ${f.field}. March rations already packed: ${s!.playerArmy.campaignSupplyReserveRice} Rice.</p><p>Labor output counts complete groups of 100 effective workers, multiplied by local yield. Public order affects how many workers are effective. Tax collections use registered households, the tax rate and the chapter’s collection factor.</p></details>${btn('Return','close')}`);break;}
 case 'routes':this.modal('Roads and days of march',campaign.map.routes.map(r=>`<p>${esc(placeNames[r.a]??nice(r.a))} ↔ ${esc(placeNames[r.b]??nice(r.b))}: about ${daysBetween(r.a,r.b)??r.travelPoints} days’ march</p>`).join('')+'<p class="muted">Days are game-scaled approximations of travel in 1600.</p>'+btn('Return','close'));break;
 case 'save':this.confirm('Save this campaign?','This replaces the selected manual slot.',()=>{void this.save(value as Slot).then(()=>this.render());});break;
 case 'delete':this.confirm('Delete this save?','This removes the selected slot from this device.',()=>{void deleteSlot(value as Slot).then(()=>this.refreshSlots()).then(()=>this.render());});break;
 case 'rename':this.modal('Rename save',`<label>Save label<input id="save-label" maxlength="40" value="${esc(this.slots[value as Slot]?.slotLabel)}"></label>${btn('Rename','rename-confirm:'+value)}`);break;
 case 'rename-confirm':{const e=this.slots[value as Slot]!;const label=(this.root.querySelector('#save-label') as HTMLInputElement).value;await writeSlot(value as Slot,await envelope(e.state,label));await this.refreshSlots();this.render();break;}
 case 'export':download('Sekigahara-'+value+'.mcsave.json',await rawSlot(value as Slot));break;
 case 'legacy-backups':{const backups=await legacyBackups();if(!backups.length)this.message('No migrated original saves are stored on this device.');else{this.legacyExportCandidates=backups;this.modal('Preserved original saves',backups.map((e,i)=>`<p>${esc(e.slotLabel)} · ${esc(e.savedAt)}</p>${btn('Export this original','legacy-export:'+i)}`).join('')+btn('Return','close'));}break;}
 case 'legacy-export':{const e=this.legacyExportCandidates[Number(value)];if(e)download('Sekigahara-v02-original-'+value+'.mcsave.json',e);break;}
 case 'export-current':if(this.practicing)return this.message('Practice does not create campaign saves. Return to your campaign to export it.');download('Sekigahara-current.mcsave.json',await envelope(s!));break;
 case 'import-paste':case 'import':{const file=(this.root.querySelector('#import') as HTMLInputElement).files?.[0];if(kind==='import'&&!file)return this.message('Select a save file first.');const raw=kind==='import-paste'?(this.root.querySelector('#import-text') as HTMLTextAreaElement).value:await file!.text();if(!raw.trim())return this.message('Paste all the exported save text first.');const e=await verify(JSON.parse(raw));this.confirm('Import to Slot 3?','The validated save replaces manual slot 3. Other slots remain unchanged.',()=>{void writeSlot('manual-3',e).then(()=>this.refreshSlots()).then(()=>this.render());});break;}
 case 'apply-settings':for(const k of ['muted','reduced','large','legible','skipAnimation'] as const)this.settings[k]=(this.root.querySelector('#'+k) as HTMLInputElement).checked;this.settings.music=Number((this.root.querySelector('#music') as HTMLInputElement).value);this.settings.effects=Number((this.root.querySelector('#effects') as HTMLInputElement).value);{let stored=true;try{localStorage.setItem('mc-settings',JSON.stringify(this.settings));}catch{stored=false;}this.render();this.message(stored?'Settings saved.':'Settings applied for this session; this viewer does not allow persistent settings.');}break;
 case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else this.message('Fullscreen is not available in this viewer. The phone layout works without it.');break;
 case 'report':this.tab=value;this.render();break;
 case 'report-json':download('Sekigahara-report.json',{version:s!.buildVersion,seed:seedText(s!.seed),realm:s!.ending,mathematics:s!.challengeRecords,decisions:s!.decisions,history:text('history.compression_disclosure')});break;
 case 'report-html':{const body=`<!doctype html><meta charset="UTF-8"><title>Sekigahara campaign report</title><h1>The Road to Sekigahara</h1><p>A WILLIAM MCADA PRODUCT</p><p>Campaign reference ${seedText(s!.seed)} · ${s!.buildVersion}</p><h2>Realm</h2><p>${esc(text('ending.'+s!.ending!.tier+'.title'))} · ${s!.ending!.realm}/100</p><h2>Mathematics</h2><p>Mastery ${s!.ending!.mastery}/100</p>${s!.challengeRecords.map(c=>`<p>${esc(c.skillTags.map(nice).join(', '))}: ${esc(pathNames[c.path])}; ${esc(Object.entries(c.answer).map(([k,v])=>fieldName(k)+' = '+v).join(', '))}</p>`).join('')}<h2>Decisions</h2>${this.ledger(s!.eventLog)}<h2>History</h2><p>${esc(text('history.compression_disclosure'))}</p><p>Historically, the Eastern coalition won in 1600. Ieyasu became shōgun in 1603.</p><footer>Designed and built by William McAda · © 2026 William McAda</footer>`;download('Sekigahara-report.html',body,'text/html');break;}
 case 'same-seed':this.state=createState(s!.seed,s!.mode,new Date().toISOString());this.view='play';this.tab='Realm';this.render();await this.save('autosave');break;
 }
 }catch(e){this.message(e instanceof Error?e.message:'The action could not be completed. Your current campaign is preserved.');}}
 tile(p:Point){const s=this.state!,b=s.battle!;this.cursor=p;const target=occupant(s,p),u=activeUnit(s);if(s.phase==='battle_deployment'){if(target?.side==='east'){this.selectedUnit=target.id;this.render();this.message('Now place '+text('formation.'+target.id)+' on an empty green starting square.');}else{const reason=deploymentBlocked(s,this.selectedUnit,p);if(reason){this.render();this.message(reason);}else this.dispatch({type:'DEPLOY',id:this.selectedUnit,point:p});}return;}if(b.councilPending)return this.message('Choose an option in the battle council first.');if(b.dispatchPending)return this.message('Read the reinforcement dispatch first.');if(u?.side!=='east'){if(target)this.selectedUnit=target.id;this.render();this.message(this.practicing&&!this.labOptions.automaticEnemy?'The enemy is paused. Use “Let enemy act” to continue.':this.enemyPaused?'Enemy turn, paused. Tap Resume or Next enemy action.':'Enemy turn. Your units act next.');return;}if(this.battleMode==='inspect'){if(target?.id===u.id){this.ringOpen=!this.ringOpen;this.inspecting=false;this.render();return;}if(target?.side==='west'&&!u.attacked&&u.ap>0){const k=defaultAttack(s,u,target);if(!k){this.selectedUnit=target.id;this.inspecting=true;this.render();this.message(attackBlocked(s,u,target,u.archetype==='arquebus'?'volley':'attack')??'That enemy is out of reach.');return;}this.battleMode=k;}else if(!target&&u.ap>0&&reachable(s,u).some(t=>t.x===p.x&&t.y===p.y))this.battleMode='move';else{if(target){this.selectedUnit=target.id;this.inspecting=true;}this.render();if(!target)this.message('Tap a green square to move, a red enemy to attack, or your gold unit for more orders.');return;}}
 let action:BattleAction|null=null,reason=commandBlocked(s,this.battleMode);if(!reason){if(this.battleMode==='move'){if(reachable(s,u).some(t=>t.x===p.x&&t.y===p.y))action={kind:'move',point:p};else reason=target?'That square is occupied. Choose an empty green square.':terrain(s,p)==='stream'?'The stream must be crossed at a bridge. Choose a green square.':'That square is beyond this move or blocked by terrain. Choose a green square.';}else if(['attack','charge','volley','suppress'].includes(this.battleMode)){reason=target?attackBlocked(s,u,target,this.battleMode):'Choose an enemy unit on a red target square.';if(!reason&&target)action={kind:this.battleMode as 'attack'|'charge'|'volley'|'suppress',target:target.id};}else if(this.battleMode==='pontoon'){if(pontoonTiles(s,u).some(t=>t.x===p.x&&t.y===p.y))action={kind:'pontoon',point:p};else reason='Choose a marked adjacent water square.';}else if(this.battleMode==='rally'){if(target?.side==='east'&&alive(target))action={kind:'rally',target:target.id};else reason='Choose one of your units to receive the Rally.';}}
 if(reason){this.render();this.message(reason);return;}const chosen=action as BattleAction|null;if(chosen&&chosen.kind==='move'){this.battleMode='inspect';this.selectedUnit=u.id;this.dispatch({type:'BATTLE',id:u.id,action:chosen});return;}if(action&&target&&['attack','charge','volley','suppress'].includes(action.kind)){const range=combatRange(s,u,target,action.kind),mid=(r:number[])=>num(Math.round((r[0]+r[1])/2/10)*10);this.pendingBattle={id:u.id,action};this.battleMode='inspect';this.modal(`${commandNames[action.kind]?.split(' ·')[0]??nice(action.kind)} ${text('formation.'+target.id)}?`,`<div class="bv5-sheet"><div class="them"><small>THEY LOSE</small><strong>−${mid(range.defender)}</strong><span>${num(range.defender[0])}–${num(range.defender[1])}</span></div><div class="us"><small>YOU LOSE</small><strong>${range.attacker[1]?'−'+mid(range.attacker):'none'}</strong><span>${range.attacker[1]?num(range.attacker[0])+'–'+num(range.attacker[1]):'no return fire'}</span></div></div><p class="muted">${['volley','suppress'].includes(action.kind)?'Uses 1 ammunition. ':''}${action.kind==='charge'?'Costs 6 morale. ':''}${action.kind==='suppress'?'No return fire; slows their next move. ':''}Terrain: ${nice(terrain(s,target))}.</p><div class="row">${btn(commandNames[action.kind]?.split(' ·')[0]??'Attack','battle-confirm',false,'primary')}${btn('Cancel','close')}</div>`,()=>this.root.querySelector('dialog')?.classList.add('bv5-dialog'));return;}if(action){const captured=action;let explanation=action.kind==='pontoon'?`Build a bridge at ${p.x+1},${p.y+1}. One action; both armies may cross it. Your prepared fieldworks paid for this crew.`:action.kind==='move'?`Move ${text('formation.'+u.id)} to column ${p.x+1}, row ${p.y+1}. This uses one action.`:action.kind==='rally'?`Spend 10 Authority and one action to restore 15 morale to ${text('formation.'+target!.id)}.`:`${text('formation.'+u.id)} will ${action.kind==='volley'?'fire at':'attack'} ${text('formation.'+target!.id)}. This uses one action${['volley','suppress'].includes(action.kind)?' and one ammunition charge':''}.`;if(target&&['attack','charge','volley','suppress'].includes(action.kind)){const range=combatRange(s,u,target,action.kind);explanation+=` Primary damage: ${range.defender[0]}–${range.defender[1]} troops. Retaliation: ${range.attacker[0]}–${range.attacker[1]} troops. Terrain: ${nice(terrain(s,target))}.${action.kind==='charge'?' Charge costs 6 morale.':''}${action.kind==='suppress'?' Suppress prevents retaliation and restricts the next target activation.':''}`;}this.confirm((commandNames[action.kind]??nice(action.kind))+'?',explanation,()=>{this.battleMode='inspect';this.selectedUnit=u.id;this.dispatch({type:'BATTLE',id:u.id,action:captured});});return;}this.render();this.announceTile();}
 tactic(kind:string){const s=this.state!,reason=commandBlocked(s,kind);if(reason)return this.message(reason);const u=activeUnit(s)!;if(kind==='resupply'){const max=Math.min(4,Math.floor(s.resources.food/s.battle!.quota.east));this.modal('Buy future rations',`<p>One action at your camp; ${s.battle!.quota.east} Rice per future pack.</p>${max?Array.from({length:max},(_,i)=>btn(`${i+1} packs · ${(i+1)*s.battle!.quota.east} Rice`,'resupply:'+(i+1))).join(''):'<p>Not enough uncommitted Rice for one pack.</p>'}${btn('Back','close')}`);return;}if(['defend','brace','forced_step','end'].includes(kind)){this.battleMode='inspect';this.dispatch({type:'BATTLE',id:u.id,action:{kind:kind as 'defend'|'brace'|'forced_step'|'end'}});}else{this.battleMode=kind;this.selectedUnit=u.id;this.render();this.message(kind==='rally'?'Choose your unit to restore 15 morale.':kind==='move'?'Choose a green square to move.':kind==='volley'?'Choose a red target within two squares in a clear row or column.':'Choose a red target directly beside the acting unit.');}}
 announceTile(){const s=this.state!,u=activeUnit(s),t=occupant(s,this.cursor),r=u?reachable(s,u).some(p=>p.x===this.cursor.x&&p.y===this.cursor.y):false;const announcer=document.querySelector('#announcer');if(announcer)announcer.textContent=`Column ${this.cursor.x+1}, row ${this.cursor.y+1}. ${nice(terrain(s,this.cursor))}. ${t?text('formation.'+t.id)+', '+t.troops+' troops, morale '+t.morale+', '+(supplied(s,t)?'supplied':'unsupplied'):'Empty'}. ${r?'Reachable':'Not reachable'}.`;}
 key(e:KeyboardEvent){if(e.key==='F11'){e.preventDefault();void this.action('fullscreen');return;}if((e.target as HTMLElement).matches('input,select,textarea')||this.root.querySelector('dialog[open]'))return;if(this.state&&this.view==='play'&&['battle_round','battle_deployment'].includes(this.state.phase)){const d:Record<string,Point>={ArrowUp:{x:0,y:-1},w:{x:0,y:-1},ArrowDown:{x:0,y:1},s:{x:0,y:1},ArrowLeft:{x:-1,y:0},a:{x:-1,y:0},ArrowRight:{x:1,y:0},d:{x:1,y:0}};if(d[e.key]){e.preventDefault();this.cursor={x:Math.max(0,Math.min(this.state.battle!.terrain[0].length-1,this.cursor.x+d[e.key].x)),y:Math.max(0,Math.min(this.state.battle!.terrain.length-1,this.cursor.y+d[e.key].y))};this.root.querySelectorAll('[role=gridcell]').forEach(el=>{const cell=el as HTMLButtonElement,selected=Number(cell.dataset.x)===this.cursor.x&&Number(cell.dataset.y)===this.cursor.y;cell.tabIndex=selected?0:-1;cell.classList.toggle('selected',selected);if(selected)cell.focus();});this.announceTile();}if(e.key==='Enter'&&(e.target as HTMLElement).matches('[role=gridcell]')){e.preventDefault();this.tile(this.cursor);}}}
}

// v0.4 (§3.1): finished painted art replaces the older stamped plates.
const paintedPlates:Record<string,string>={EVENT_CH1_REGENTS:'CH1-P1',EVENT_CH2_AIZU:'CH2-P1',EVENT_CH3_FUSHIMI:'CH3-P2',EVENT_CH4_MINO:'CH4-P2',EVENT_CRISIS_FAMINE:'CRISIS-FAMINE',EVENT_CRISIS_FLOOD:'CRISIS-FLOOD',EVENT_CRISIS_PLAGUE:'CRISIS-PLAGUE',EVENT_CRISIS_RAID:'CRISIS-RAID',EVENT_CRISIS_REBELLION:'CRISIS-REBELLION'};
const SEEN_KEY='mc-scenes-seen-v1';
function loadSeen():string[]{try{const v=JSON.parse(localStorage.getItem(SEEN_KEY)??'[]');return Array.isArray(v)?v.slice(-200):[];}catch{return [];}}
function saveSeen(set:Set<string>){try{localStorage.setItem(SEEN_KEY,JSON.stringify([...set].slice(-200)));}catch{/* storage unavailable: scenes may replay after a reload */}}

const DEV_KEY='mc-dev-options-v1';
function loadDev():DevOptions{try{return {...defaultDev,...JSON.parse(localStorage.getItem(DEV_KEY)??'{}')};}catch{return {...defaultDev};}}
function saveDev(o:DevOptions){try{localStorage.setItem(DEV_KEY,JSON.stringify(o));}catch{/* DEV options are a convenience only */}}
